import React from 'react';
import { useParams, Link } from 'react-router-dom';
import './CursoDetalle.css'; // Estilos específicos para la página de detalle del curso
import Inscripcion from './Inscripcion'; // Importar el componente Inscripcion

const CursoDetalle = () => {
  const { id } = useParams(); // Obtener el ID del curso desde la URL

  // Aquí puedes agregar la lógica para obtener los detalles del curso desde la base de datos
  const curso = {
    id,
    nombre: id === '1' ? 'Curso de React' : 'Curso de JavaScript',
    descripcion: id === '1' 
      ? 'Aprende a desarrollar aplicaciones web con React, un framework moderno y popular que te permitirá crear interfaces de usuario interactivas y eficientes. Este curso cubre desde los fundamentos hasta técnicas avanzadas, asegurando que tengas las habilidades necesarias para desarrollar aplicaciones completas.'
      : 'Domina el lenguaje de programación JavaScript, la base de la web moderna. Este curso te llevará desde los conceptos básicos hasta la programación orientada a objetos y la manipulación del DOM, preparándote para crear aplicaciones web dinámicas y funcionales.',
    precio: id === '1' ? 100 : 80,  // Ejemplo de precio
  };

  return (
    <div className="curso-detalle">
      {/* Información del curso */}
      <h1>{curso.nombre}</h1>
      <p>{curso.descripcion}</p>
      <p><strong>Precio: ${curso.precio}</strong></p>

      {/* Botón de compra */}
      <div className="boton-compra">
        <Link to={`/pago/${curso.id}`} className="btn-compra">Comprar ahora</Link>
      </div>

      <Inscripcion cursoId={curso.id} />
    </div>
  );
};

export default CursoDetalle;
